'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let ptr = 0;

const N = data[ptr++];
const parent = new Int32Array(N + 1);
const children = Array.from({ length: N + 1 }, () => []);

for (let v = 2; v <= N; v++) {
  parent[v] = data[ptr++];
  children[parent[v]].push(v);
}

const Q = data[ptr++];
const BLOCK_SIZE = 256;
const BLOCK_SHIFT = 8;

const size = new Int32Array(N + 1);
const heavy = new Int32Array(N + 1);
const largestChild = new Int32Array(N + 1);
size.fill(1);

for (let v = N; v >= 2; v--) {
  const p = parent[v];
  size[p] += size[v];
  if (size[v] > largestChild[p]) {
    largestChild[p] = size[v];
    heavy[p] = v;
  }
}

const head = new Int32Array(N + 1);
const chainId = new Int32Array(N + 1);
const chainOffset = new Int32Array(N + 1);
const chains = [];
const starts = [1];

while (starts.length) {
  const start = starts.pop();
  const id = chains.length;
  const nodes = [];

  for (let v = start; v !== 0; v = heavy[v]) {
    head[v] = start;
    chainId[v] = id;
    chainOffset[v] = nodes.length;
    nodes.push(v);

    for (const child of children[v]) {
      if (child !== heavy[v]) starts.push(child);
    }
  }

  const blocks = [];
  for (let i = 0; i < nodes.length; i += BLOCK_SIZE) {
    blocks.push({
      nodes: nodes.slice(i, Math.min(i + BLOCK_SIZE, nodes.length)),
      offsets: [],
      values: [],
      recordNodes: []
    });
  }
  chains.push({ blocks });
}

const LOG = 17;
const ancestors = Array.from({ length: LOG }, () => new Int32Array(N + 1));
ancestors[0].set(parent);
for (let j = 1; j < LOG; j++) {
  const prev = ancestors[j - 1];
  const curr = ancestors[j];
  for (let v = 1; v <= N; v++) curr[v] = prev[prev[v]];
}

function getAncestor(v, steps) {
  let bit = 0;
  while (steps > 0) {
    if (steps & 1) v = ancestors[bit][v];
    steps >>= 1;
    bit++;
  }
  return v;
}

const updateTime = new Int32Array(N + 1);

function rebuildBlock(block) {
  block.offsets.length = 0;
  block.values.length = 0;
  block.recordNodes.length = 0;

  let maxValue = 0;
  for (let i = 0; i < block.nodes.length; i++) {
    const v = block.nodes[i];
    const value = updateTime[v];
    if (value > maxValue) {
      maxValue = value;
      block.offsets.push(i);
      block.values.push(value);
      block.recordNodes.push(v);
    }
  }
}

const output = [];
let timestamp = 0;

for (let qi = 0; qi < Q; qi++) {
  const type = data[ptr++];

  if (type === 2) {
    const v = data[ptr++];
    updateTime[v] = ++timestamp;

    const chain = chains[chainId[v]];
    const block = chain.blocks[chainOffset[v] >> BLOCK_SHIFT];
    rebuildBlock(block);
  } else {
    const v = data[ptr++];
    const k = data[ptr++];

    const segments = [];
    let cur = parent[v];

    while (cur !== 0) {
      segments.push({
        id: chainId[cur],
        endOffset: chainOffset[cur]
      });
      cur = parent[head[cur]];
    }
    segments.reverse();

    function scan(target) {
      let threshold = 0;
      let seen = 0;

      for (const segment of segments) {
        const chain = chains[segment.id];
        const endBlock = segment.endOffset >> BLOCK_SHIFT;

        for (let bi = 0; bi <= endBlock; bi++) {
          const block = chain.blocks[bi];
          const cutoff = bi === endBlock
            ? segment.endOffset & (BLOCK_SIZE - 1)
            : block.nodes.length - 1;

          let lo = 0;
          let hi = block.offsets.length;
          while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (block.offsets[mid] <= cutoff) lo = mid + 1;
            else hi = mid;
          }
          const limit = lo;

          lo = 0;
          hi = limit;
          while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (block.values[mid] <= threshold) lo = mid + 1;
            else hi = mid;
          }
          const first = lo;
          const count = limit - first;

          if (target > 0 && target <= seen + count) {
            return block.recordNodes[first + target - seen - 1];
          }

          seen += count;
          if (limit > 0 && block.values[limit - 1] > threshold) {
            threshold = block.values[limit - 1];
          }
        }
      }

      return target === 0 ? seen : 0;
    }

    const recordCount = scan(0);
    let answer;

    if (k <= recordCount) {
      answer = scan(recordCount - k + 1);
    } else if (recordCount === 0) {
      answer = getAncestor(v, k);
    } else {
      const topRecord = scan(1);
      answer = getAncestor(topRecord, k - recordCount);
    }

    output.push(String(answer));
  }
}

console.log(output.join('\n'));
